using FsCheck;
using FsCheck.Fluent;
namespace Atm.Tests;
public class Mesure(Xunit.Abstractions.ITestOutputHelper o)
{
    [Fact]
    public void Repartition()
    {
        var servables = Domaine.RetraitServable().Generator.Sample(200, 50);
        var passes = servables.Select(r => { var d = r.Situation.Doublure(); new CashMachine(d).Execute(r.Situation.Account, new Operation.Withdraw(r.Amount)); return d.DispenseCalls.Count; });
        o.WriteLine("passes: " + string.Join(", ", passes.GroupBy(x => x).OrderBy(g => g.Key).Select(g => $"{g.Key}:{g.Count()}")));
        var small = servables.Count(r => { var n = new CashMachine(r.Situation.Module()).Execute(r.Situation.Account, new Operation.Withdraw(r.Amount)).Notes; return n.Fifties <= 1 && n.Twenties <= 1 && n.Tens <= 1; });
        o.WriteLine($"retrait redéposable: {small}/200");
        o.WriteLine("fees: " + servables.Count(r => r.Amount > 100));
        var gen = from s in Domaine.Situation().Generator from a in Domaine.Montant().Generator select new CashMachine(s.Module()).Execute(s.Account, new Operation.Withdraw(a.Value)).Status;
        o.WriteLine("statuts retrait: " + string.Join(", ", gen.Sample(200, 50).GroupBy(x => x).Select(g => $"{g.Key}:{g.Count()}")));
        var genD = from s in Domaine.Situation().Generator from a in Domaine.Depot().Generator select new CashMachine(s.Module()).Execute(s.Account, new Operation.Deposit(a.Notes)).Status;
        o.WriteLine("statuts dépôt: " + string.Join(", ", genD.Sample(200, 50).GroupBy(x => x).Select(g => $"{g.Key}:{g.Count()}")));
        var parcours = Domaine.Parcours().Generator.Sample(200, 50);
        o.WriteLine("longueur parcours moy: " + parcours.Average(p => p.Pas.Length));
    }
}
EOF
cd /tmp/atmcopy && dotnet test --filter Mesure --logger "console;verbosity=detailed" 2>&1 | grep -E "passes|redépo|fees|statuts|longueur|error"

