    }

    [Property(Replay = "42,1", MaxTest = 200, Arbitrary = [typeof(Domaine)])]
    public void Depot_Admis_CrediteLeCompteEtRangeLesBillets(DepotAdmis d)
    {
        var s = d.Situation;
        var module = s.Module();

        var result = Executer(module, s.Account, new Operation.Deposit(d.Notes));

